"""Data behind the Atlas's reading panel and its unread layer, generated by the site build.

  docs/atlas/<slug>.json   what the panel shows for one write-up: its cipher snip with the credit, the cipher system,
                           and per document the summary and an excerpt of the English text. Fetched when a letter opens.
  docs/atlas-open.json     the open catalogue letters that can be placed on the map, for the unread layer.
  docs/atlas_stories.json  hand-written chapters; check_stories() refuses a chapter pointing at a letter not on the map.
  docs/atlas_people.json   hand-written: the people of a letter that differ from its write-up's. apply_people() copies
                           them into atlas.json as the letter's "who"; a write-up's people otherwise stand for all its letters.

What may be shown follows _texts.py: nothing from a target with outcome.texts_withheld (fr. 3029/3092 and the like), and
English text only for an entry a reader has passed (state read or read in part, grade A or B).
"""
import html, json, pathlib, re, sys

import _texts as TX

HERE = pathlib.Path(__file__).resolve().parent
ROOT = HERE.parent
OUT = HERE / 'atlas'
EXCERPT = 900      # characters of English in the panel; the write-up has the rest
TEXT_FILES = ('.md', '.txt')


def plain(s):
    return html.unescape(re.sub(r'<[^>]+>', '', str(s or ''))).strip()


# a first paragraph that only says how the file was made; the panel has its own note on holes and the write-up the rest
PREAMBLE = re.compile(r'^(Translat|Our translation|Working translation|Conventions|Deciphered words|English translation)', re.I)


def clean_summary(s):
    """A summary without the sentences that talk about repository files."""
    s = plain(s)
    keep = [x for x in re.split(r'(?<=[.!?])\s+(?=[A-Z"“‘\[])', s) if not re.search(r'[\w-]+\.(md|txt|tsv|py|json)(?!\w)|[a-z_]+/[\w.-]+', x)]
    return ' '.join(keep) or s


def excerpt(path):
    """The opening of a text file as prose, cut at a sentence end. (text, whether it was cut); ('', False) for
    anything that is not prose, such as a line-by-line working or a raw decode."""
    if not path.is_file() or path.suffix.lower() not in TEXT_FILES: return '', False
    raw = re.sub(r'<!--.*?-->', '', path.read_text(encoding='utf-8', errors='ignore'), flags=re.S)
    lines = []
    for ln in raw.splitlines():
        ln = ln.strip()
        if ln.startswith(('#', '---')): continue
        lines.append(re.sub(r'[*_`]{1,3}(?=\S)|(?<=\S)[*_`]{1,3}', '', ln))
    paras = [p.strip() for p in re.split(r'\n\s*\n', '\n'.join(lines)) if p.strip()]
    if paras and PREAMBLE.match(paras[0]): paras = paras[1:]
    text = re.sub(r'^(?:[…\s]|\[…\]|\[\.\.\.\])+', '', '\n\n'.join(paras))
    if len(text) < 60 or not re.search(r'[.;:!?]', text): return '', False
    if sum(c.isdigit() for c in text) / len(text) > .08 or text.count('|') > 3: return '', False
    if len(text) <= EXCERPT: return text, False
    head = text[:EXCERPT]
    ends = [m.end() for m in re.finditer(r'[.;:!?]["”’)\]]?(?=\s)', head)]
    return head[:ends[-1] if ends and ends[-1] > EXCERPT // 3 else EXCERPT].rstrip(), True


def english(folder, t, shared):
    """English an entry may show, under the reading gate; ('', False) when it has none. A file that holds several
    documents is left out: its opening belongs to another letter."""
    if TX.entry_state(t) not in TX.READING: return '', False
    if (t.get('reading_review') or TX.audit_review(folder, t)).get('grade') not in ('A', 'B'): return '', False
    lang = (t.get('language') or '').lower()
    kinds = ('translation', 'reading') if lang == 'en' else ('translation',)
    for k in kinds:
        for f in TX.listify(t.get(k)):
            if str(f).startswith('http') or (folder, str(f)) in shared: continue
            text, cut = excerpt(folder / f)
            if text: return text, cut
    return '', False


def shared_files(folder, texts):
    seen, shared = set(), set()
    for t in texts:
        files = {str(f) for k in ('translation', 'reading') for f in TX.listify(t.get(k))}
        multi = len(TX.listify(t.get('doc'))) > 1
        for f in files:
            if multi or f in seen: shared.add((folder, f))
            seen.add(f)
    return shared


def contributed(page):
    """The people a contributed or mixed result is credited to, for the panel's byline."""
    if page.get('provenance') not in ('contributed', 'mixed'): return []
    people = json.loads((ROOT / 'contributors.json').read_text(encoding='utf-8'))
    people = people.get('contributors', people) if isinstance(people, dict) else people
    if isinstance(people, list): people = {x.get('id'): x for x in people}
    names = []
    for c in page.get('credits') or []:
        w = people.get(c.get('who')) or {}
        if w.get('kind') == 'person' and w.get('name') not in names: names.append(w.get('name'))
    return names


def target_record(page, profiles, images):
    rec = {'letters': {}}
    im = images.get(page['slug'])
    if im: rec['snip'] = {'src': im[0], 'cap': plain(im[1]), 'credit': plain(im[2])}
    for f in page.get('folders') or []:
        o = profiles[f].get('outcome') or {}
        if not rec.get('system'):
            s = plain((profiles[f].get('system') or {}).get('summary'))
            if s: rec['system'] = s[:260].rsplit(' ', 1)[0] + '…' if len(s) > 260 else s
        if o.get('texts_withheld'):
            rec['withheld'] = True
            continue
        folder = ROOT / 'targets' / f
        shared = shared_files(folder, o.get('texts') or [])
        for t in o.get('texts') or []:
            entry = {'state': TX.entry_state(t)}
            if t.get('summary'): entry['summary'] = clean_summary(t['summary'])
            if isinstance(t.get('read_share'), (int, float)): entry['share'] = t['read_share']
            en, cut = english(folder, t, shared)
            if en: entry.update(en=en, cut=cut, lang=t.get('language') or '')
            for d in TX.listify(t.get('doc')) or ['all']:
                rec['letters'].setdefault(str(d), entry)
    names = contributed(page)
    if names: rec['by'] = names
    return rec


def write_targets(pages, profiles, images):
    """One file per write-up on the map; files for write-ups that left the map go. Returns (files, letters with a text)."""
    at = json.loads((HERE / 'atlas.json').read_text(encoding='utf-8'))
    by_slug = {p['slug']: p for p in pages}
    OUT.mkdir(exist_ok=True)
    keep, texts = set(), 0
    for slug in sorted({l['slug'] for l in at['letters']}):
        if slug not in by_slug: continue
        rec = target_record(by_slug[slug], profiles, images)
        name = slug + '.json'; keep.add(name)
        (OUT / name).write_text(json.dumps(rec, ensure_ascii=False, separators=(',', ':')), encoding='utf-8')
        docs = rec['letters']
        texts += sum(1 for l in at['letters'] if l['slug'] == slug and (l['doc'] in docs or 'all' in docs))
    for old in OUT.glob('*.json'):
        if old.name not in keep: old.unlink()
    return len(keep), texts


def write_open():
    """The open catalogue letters whose place the gazetteer knows. An entry with no such place stays off the map."""
    sys.path.insert(0, str(ROOT / 'tools'))
    import atlas_places as AP
    import _catalogue_page as C
    at = json.loads((HERE / 'atlas.json').read_text(encoding='utf-8'))
    names = AP.gazetteer(at)
    cat = json.loads((ROOT / 'catalogue.json').read_text(encoding='utf-8'))
    entries = cat if isinstance(cat, list) else cat['entries']
    rows, places = [], {}
    for e in entries:
        if not C.is_open(e) or e.get('writeup') or not isinstance(e.get('year'), int): continue
        pl = AP.place_in(re.split(r'\s*(?:->|→)\s*', str(e.get('place') or ''))[0], names)
        if not pl: continue
        places[pl] = names[pl]
        rows.append({'id': e['id'], 'y': e['year'], 'at': pl, 't': plain(e.get('title'))})
    rows.sort(key=lambda r: (r['y'], r['id']))
    (HERE / 'atlas-open.json').write_text(json.dumps({'places': places, 'letters': rows}, ensure_ascii=False, separators=(',', ':')), encoding='utf-8')
    return len(rows), sum(1 for e in entries if C.is_open(e) and not e.get('writeup'))


def apply_people():
    """Give each letter listed in atlas_people.json its own people, with the portrait of anyone _portraits.json knows."""
    listed = {k: v for k, v in json.loads((HERE / 'atlas_people.json').read_text(encoding='utf-8')).items() if not k.startswith('_')}
    imgs = {}
    for ps in json.loads((HERE / '_portraits.json').read_text(encoding='utf-8')).values():
        for q in ps:
            if q.get('img'): imgs[q['name']] = q['img']
    at = json.loads((HERE / 'atlas.json').read_text(encoding='utf-8'))
    role = {'s': 'sender', 'r': 'recipient', 'p': 'party'}
    done = set()
    for l in at['letters']:
        l.pop('who', None)
        ps = listed.get(l['slug'], {}).get(l['doc'])
        if ps is None: continue
        l['who'] = [{'role': role[r], 'name': n, 'img': imgs.get(n)} for r, n in ps]
        done.add((l['slug'], l['doc']))
    bad = [f'{s} {d}' for s, ds in listed.items() for d in ds if (s, d) not in done]
    if bad: raise SystemExit('docs/atlas_people.json names letters not on the map:\n  ' + '\n  '.join(bad))
    (HERE / 'atlas.json').write_text(json.dumps(at, ensure_ascii=False, indent=1) + '\n', encoding='utf-8')
    return len(done)


def check_stories():
    """Every letter a chapter spotlights has to be on the map, or the chapter would open nothing."""
    p = HERE / 'atlas_stories.json'
    if not p.exists(): return 0
    stories = json.loads(p.read_text(encoding='utf-8'))
    on_map = {(l['slug'], l['doc']) for l in json.loads((HERE / 'atlas.json').read_text(encoding='utf-8'))['letters']}
    bad = [f"{s['id']}: {x['slug']} {x['doc']}" for s in stories for x in s.get('letters', []) if (x['slug'], x['doc']) not in on_map]
    if bad: raise SystemExit('docs/atlas_stories.json points at letters not on the map:\n  ' + '\n  '.join(bad))
    return len(stories)


def build(pages, profiles, images):
    return write_targets(pages, profiles, images), write_open(), check_stories(), apply_people()
